pragma solidity ^0.8.19;
import {
    StreamArtistRecoveredSimpleHydration as RecoveredSimple
} from "./StreamArtistRecoveredSimpleHydration.sol";
import {
    StreamArtistRecoveredHydrationCodec as RecoveredCodec
} from "./StreamArtistRecoveredHydrationCodec.sol";
import {
    StreamArtistRecoveredHydrationTypes as RecoveredRH
} from "../../interfaces/stream/artist/StreamArtistRecoveredHydrationTypes.sol";
import "./StreamArtistMultipleDelegationCollectionHydration.sol";
import "./StreamArtistMultipleCollectionHydration.sol";

import "./StreamArtistOwner.sol";
import "./StreamArtistCollaboratorHashes.sol";
import "./StreamArtistCurrentAuthorityFacts.sol";
import {
    StreamArtistOnboardingTypes as T
} from "../../interfaces/stream/artist/StreamArtistOnboardingTypes.sol";

/// @notice Sole owner of acceptance records and acceptance-domain events.
contract StreamArtistAcceptanceLifecycle is StreamArtistOwner {
    struct CollaboratorEventContext {
        bytes32 artistId;
        uint8 authorityClass;
        uint256 nonce;
        bytes32 record;
    }

    mapping(bytes32 => bytes32) public acceptanceRecord;
    mapping(bytes32 => uint64) public acceptedAt;
    mapping(bytes32 => bytes32) private _collaboratorRecords;
    event CollaboratorAccepted(
        uint16 schemaVersion,
        uint256 indexed collectionId,
        address indexed collaborator,
        bytes32 indexed collaboratorArtistId,
        uint64 bindingGeneration,
        bytes32 role,
        bytes32 shareLabelId,
        uint8 authorityClass,
        uint256 nonce,
        uint64 signedAt,
        bytes32 acceptanceRecordHash,
        bytes32 bindingHash
    );
    event ArtistBindingAccepted(
        uint16 schemaVersion,
        uint256 indexed collectionId,
        bytes32 indexed artistId,
        address indexed signer,
        uint64 bindingGeneration,
        bytes32 bindingHash,
        uint8 authorityClass,
        uint256 nonce,
        uint64 signedAt,
        bytes32 acceptanceRecordHash
    );
    constructor(
        address registry_,
        address coordinator_,
        address archive_,
        address core_,
        address manager_
    )
        StreamArtistOwner(
            registry_,
            coordinator_,
            archive_,
            keccak256("domain:acceptance_lifecycle"),
            core_,
            manager_
        )
    { }

    function recordAcceptance(
        T.ActionContext calldata c,
        uint256 collectionId,
        T.Binding calldata b,
        address signer,
        uint256 nonce
    ) external returns (bytes32 record) {
        _check(c, 2);
        if (signer != b.artistAddress) revert T.InvalidRecord();
        return _recordAcceptance(c, collectionId, b, signer, nonce, 1);
    }

    function recordAcceptanceWithAuthority(
        T.ActionContext calldata c,
        uint256 collectionId,
        T.Binding calldata b,
        R.AuthorityFact calldata authority,
        address signer,
        uint256 nonce
    ) external returns (bytes32) {
        _check(c, 2);
        StreamArtistCurrentAuthorityFacts.requirePrincipal(b.artistId, signer, authority, false);
        return _recordAcceptance(c, collectionId, b, signer, nonce, authority.authorityClass);
    }

    function _recordAcceptance(
        T.ActionContext calldata c,
        uint256 collectionId,
        T.Binding calldata b,
        address signer,
        uint256 nonce,
        uint8 authorityClass
    ) private returns (bytes32 record) {
        if (b.accepted || b.bindingHash == bytes32(0)) {
            revert T.InvalidRecord();
        }
        record = StreamArtistHashes.acceptanceRecordForAuthority(
            _environment(), collectionId, b, signer, authorityClass, nonce, _now()
        );
        bytes32 key = _consume(
            keccak256("acceptance_lifecycle.replay.record_uniqueness"),
            keccak256(abi.encode(collectionId, b.generation, uint8(1), signer)),
            record
        );
        acceptanceRecord[b.bindingHash] = record;
        acceptedAt[b.bindingHash] = _now();
        _commit(
            c,
            keccak256(abi.encode(collectionId, b, signer, nonce)),
            keccak256(abi.encode(b.bindingHash, record)),
            keccak256(abi.encode(key, record)),
            record
        );
        _native(c.operationId, record, b.artistId, collectionId);
        emit ArtistBindingAccepted(
            1,
            collectionId,
            b.artistId,
            signer,
            b.generation,
            b.bindingHash,
            authorityClass,
            nonce,
            _now(),
            record
        );
    }

    function collaboratorAcceptanceRecord(
        bytes32 bindingHash,
        address account,
        bytes32 role,
        bytes32 shareLabelId
    ) external view returns (bytes32) {
        return _collaboratorRecords[
            StreamArtistCollaboratorHashes.rowKey(bindingHash, account, role, shareLabelId)
        ];
    }

    function recordCollaboratorAcceptance(
        T.ActionContext calldata c,
        C.BindingAcceptance calldata p,
        bytes32 artistId,
        uint256 nonce
    ) external returns (bytes32 record) {
        return _recordCollaboratorAcceptance(c, p, artistId, nonce, 1);
    }

    function recordCollaboratorAcceptanceWithAuthority(
        T.ActionContext calldata c,
        C.BindingAcceptance calldata p,
        bytes32 artistId,
        uint256 nonce,
        R.AuthorityFact calldata authority
    ) external returns (bytes32) {
        _check(c, 7);
        StreamArtistCurrentAuthorityFacts.requirePrincipal(artistId, p.account, authority, false);
        return _recordCollaboratorAcceptance(c, p, artistId, nonce, authority.authorityClass);
    }

    function _recordCollaboratorAcceptance(
        T.ActionContext calldata c,
        C.BindingAcceptance calldata p,
        bytes32 artistId,
        uint256 nonce,
        uint8 authorityClass
    ) private returns (bytes32 record) {
        _check(c, 7);
        if (
            p.collectionId == 0 || p.generation == 0 || p.bindingHash == bytes32(0)
                || p.account == address(0) || artistId == bytes32(0)
        ) revert T.InvalidRecord();
        record = StreamArtistCollaboratorHashes.acceptanceRecordForAuthority(
            _environment(), p, authorityClass, nonce, _now()
        );
        bytes32 row =
            StreamArtistCollaboratorHashes.rowKey(p.bindingHash, p.account, p.role, p.shareLabelId);
        bytes32 key = _consume(
            keccak256("acceptance_lifecycle.replay.record_uniqueness"),
            keccak256(
                abi.encode(
                    p.collectionId, p.generation, uint8(2), p.account, p.role, p.shareLabelId
                )
            ),
            record
        );
        _collaboratorRecords[row] = record;
        _commit(
            c,
            keccak256(abi.encode(p, artistId, nonce)),
            keccak256(abi.encode(row, artistId, record)),
            keccak256(abi.encode(key, record)),
            record
        );
        _native(c.operationId, record, artistId, p.collectionId);
        _emitCollaboratorAcceptance(
            p, CollaboratorEventContext(artistId, authorityClass, nonce, record)
        );
    }

    function _emitCollaboratorAcceptance(
        C.BindingAcceptance calldata p,
        CollaboratorEventContext memory eventContext
    ) private {
        emit CollaboratorAccepted(
            1,
            p.collectionId,
            p.account,
            eventContext.artistId,
            p.generation,
            p.role,
            p.shareLabelId,
            eventContext.authorityClass,
            eventContext.nonce,
            _now(),
            eventContext.record,
            p.bindingHash
        );
    }

    function authorityHydrationState(AH.Query calldata q)
        external
        view
        override
        returns (bytes memory)
    {
        if (acceptanceRecord[q.bindingHash] == 0 || acceptedAt[q.bindingHash] == 0) {
            revert T.InvalidRecord();
        }
        return abi.encode(AH.Acceptance(acceptanceRecord[q.bindingHash], acceptedAt[q.bindingHash]));
    }

    function _recoveredHydrationFeatures() internal pure override returns (uint256) {
        return RecoveredRH.ATTESTATION_GRAPH_FEATURES;
    }

    function recoveredAuthorityHydrationState(
        AH.Query calldata q,
        RecoveredRH.OwnerProvenance calldata local
    ) external view override returns (bytes memory) {
        return RecoveredSimple.exportAcceptance(acceptanceRecord, acceptedAt, q, local);
    }

    function _hydrateAuthority(AH.Query calldata q, AH.OwnerData calldata p) internal override {
        if (RecoveredCodec.isState(p.typedState, 3)) {
            if (_revision != 0 || p.nonces.length != 0) revert T.InvalidRecord();
            RecoveredSimple.importAcceptance(acceptanceRecord, acceptedAt, q, p.typedState);
            return;
        }
        if (StreamArtistDelegationHydrationCodec.tagged(p.typedState, MD.ACCEPTANCE)) {
            if (p.nonces.length != 0) revert T.InvalidRecord();
            StreamArtistMultipleDelegationCollectionHydration.acceptances(
                acceptanceRecord, acceptedAt, p.typedState
            );
            return;
        }
        if (StreamArtistMultipleHydrationCodec.isState(p.typedState)) {
            if (p.nonces.length != 0) revert T.InvalidRecord();
            StreamArtistMultipleCollectionHydration.acceptances(
                acceptanceRecord, acceptedAt, p.typedState
            );
            return;
        }
        AH.Acceptance memory a = abi.decode(p.typedState, (AH.Acceptance));
        if (acceptanceRecord[q.bindingHash] != 0 || p.nonces.length != 0) revert T.InvalidRecord();
        acceptanceRecord[q.bindingHash] = a.record;
        acceptedAt[q.bindingHash] = a.acceptedAt;
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;
import "../../interfaces/stream/artist/IStreamArtistReconstruction.sol";

import "../../interfaces/stream/artist/IStreamArtistArchiveV2.sol";
import "../../libraries/SSTORE2.sol";
import { StreamArtistPayloadStore } from "./StreamArtistPayloadStore.sol";

/// @notice Append-only evidence archive for the proposed artist-authority successor.
/// @dev This contract owns no semantic record or decision. It never authenticates an artist,
///      consumes replay, answers current/latest state, calls a semantic owner, or exposes a
///      mutable binding. Exact evidence must be joined to authoritative owner state elsewhere.
contract StreamArtistArchiveV2 is IStreamArtistArchiveV2, IStreamArtistPayloadArchive {
    bytes32 private constant _MARKER = keccak256("6529STREAM_ARTIST_ARCHIVE_V2");
    bytes32 private constant _BINDING_DOMAIN = keccak256("6529STREAM_ARTIST_ARCHIVE_BINDING_V2");
    uint16 private constant _SCHEMA_VERSION = 2;

    struct EvidenceRecord {
        address pointer;
        uint32 payloadSize;
        uint64 appendedAtBlock;
        bytes32 contentHash;
    }

    address public immutable override artistRegistry;
    address public immutable override operationCoordinator;
    bytes32 public immutable override artistArchiveBindingHashV2;

    mapping(bytes32 evidenceId => mapping(uint64 evidenceVersion => EvidenceRecord)) private
        _evidence;

    constructor(address artistRegistry_, address operationCoordinator_) {
        if (artistRegistry_ == address(0) || operationCoordinator_ == address(0)) {
            revert ArtistArchiveInvalidBinding(artistRegistry_, operationCoordinator_);
        }
        artistRegistry = artistRegistry_;
        operationCoordinator = operationCoordinator_;
        artistArchiveBindingHashV2 = keccak256(
            abi.encode(
                _BINDING_DOMAIN,
                block.chainid,
                artistRegistry_,
                operationCoordinator_,
                type(IStreamArtistArchiveV2).interfaceId,
                _MARKER,
                _SCHEMA_VERSION,
                SSTORE2.MAX_DATA_LENGTH
            )
        );
    }

    function supportsInterface(bytes4 interfaceId) external pure override(IERC165) returns (bool) {
        return interfaceId == type(IStreamArtistArchiveV2).interfaceId
            || interfaceId == type(IStreamArtistPayloadArchive).interfaceId
            || interfaceId == type(IStreamArtistReconstruction).interfaceId
            || interfaceId == type(IERC165).interfaceId;
    }

    function artistArchiveMarkerV2() external pure returns (bytes32) {
        return _MARKER;
    }

    function artistArchiveSchemaV2() external pure returns (uint16) {
        return _SCHEMA_VERSION;
    }

    function artistArchiveMaxEvidenceBytesV2() external pure returns (uint256) {
        return SSTORE2.MAX_DATA_LENGTH;
    }

    function appendArtistEvidenceV2(
        bytes32 evidenceId,
        uint64 evidenceVersion,
        bytes calldata evidence
    ) external returns (bytes32 contentHash, address pointer, bool appended) {
        if (msg.sender != operationCoordinator) {
            revert ArtistArchiveUnauthorizedWriter(msg.sender);
        }
        _requireValidKey(evidenceId, evidenceVersion);
        uint256 payloadSize = evidence.length;
        if (payloadSize == 0) {
            revert ArtistArchiveEmptyEvidence(evidenceId, evidenceVersion);
        }
        if (payloadSize > SSTORE2.MAX_DATA_LENGTH) {
            revert ArtistArchiveEvidenceTooLarge(payloadSize, SSTORE2.MAX_DATA_LENGTH);
        }
        if (block.number > type(uint64).max) {
            revert ArtistArchiveBlockNumberOverflow(block.number);
        }

        contentHash = keccak256(evidence);
        EvidenceRecord storage record = _evidence[evidenceId][evidenceVersion];
        if (record.pointer != address(0)) {
            if (record.contentHash != contentHash || record.payloadSize != payloadSize) {
                revert ArtistArchiveEvidenceConflict(
                    evidenceId, evidenceVersion, record.contentHash, contentHash
                );
            }
            return (record.contentHash, record.pointer, false);
        }

        pointer = SSTORE2.write(evidence);
        record.pointer = pointer;
        // `payloadSize <= SSTORE2.MAX_DATA_LENGTH`, so this narrowing is exact.
        // forge-lint: disable-next-line(unsafe-typecast)
        record.payloadSize = uint32(payloadSize);
        // The explicit bound above makes the frozen uint64 receipt field exact.
        // forge-lint: disable-next-line(unsafe-typecast)
        record.appendedAtBlock = uint64(block.number);
        record.contentHash = contentHash;
        StreamArtistPayloadStore.registerPointer(
            pointer, keccak256("ARTIST_OPERATION_EVIDENCE"), contentHash
        );
        emit ArtistArchiveEvidenceAppendedV2(
            evidenceId, evidenceVersion, contentHash, pointer, payloadSize
        );
        return (contentHash, pointer, true);
    }

    function artistEvidenceMetadataV2(bytes32 evidenceId, uint64 evidenceVersion)
        external
        view
        returns (bytes32 contentHash, address pointer, uint32 payloadSize, uint64 appendedAtBlock)
    {
        _requireValidKey(evidenceId, evidenceVersion);
        EvidenceRecord storage record = _evidence[evidenceId][evidenceVersion];
        if (record.pointer == address(0)) {
            revert ArtistArchiveEvidenceUnavailable(evidenceId, evidenceVersion);
        }
        return (record.contentHash, record.pointer, record.payloadSize, record.appendedAtBlock);
    }

    function artistEvidenceBytesV2(bytes32 evidenceId, uint64 evidenceVersion)
        external
        view
        returns (bytes memory evidence)
    {
        _requireValidKey(evidenceId, evidenceVersion);
        EvidenceRecord storage record = _evidence[evidenceId][evidenceVersion];
        if (record.pointer == address(0)) {
            revert ArtistArchiveEvidenceUnavailable(evidenceId, evidenceVersion);
        }
        evidence = SSTORE2.read(record.pointer);
        bytes32 observedHash = keccak256(evidence);
        if (evidence.length != record.payloadSize || observedHash != record.contentHash) {
            revert ArtistArchiveEvidenceCorrupted(
                evidenceId, evidenceVersion, record.contentHash, observedHash
            );
        }
    }

    function registerArtistStoredPayload(address pointer, bytes32 kind, bytes32 hash)
        external
        override
    {
        if (msg.sender != operationCoordinator) {
            revert ArtistArchiveUnauthorizedWriter(msg.sender);
        }
        StreamArtistPayloadStore.registerPointer(pointer, kind, hash);
    }

    function recordPreimageBytes(bytes32 hash) external view override returns (bytes memory) {
        return StreamArtistPayloadStore.recordBytes(hash);
    }

    function storedPayloadCount() external view override returns (uint256) {
        return StreamArtistPayloadStore.count();
    }

    function storedPayloadAt(uint256 index)
        external
        view
        override
        returns (address, bytes32, bytes32)
    {
        return StreamArtistPayloadStore.at(index);
    }

    function _requireValidKey(bytes32 evidenceId, uint64 evidenceVersion) private pure {
        if (evidenceId == bytes32(0) || evidenceVersion == 0) {
            revert ArtistArchiveInvalidEvidenceKey(evidenceId, evidenceVersion);
        }
    }
}

