    {
        return _additiveHydrationState();
    }

    function _additiveHydrationState() private view returns (bytes memory) {
        _baselineTiming();
        return StreamArtistAdditiveIdentityHydration.exportEncoded(
            _identity,
            _delegations,
            _identityRevisions,
            _estate,
            _dormancy,
            _unavailability,
            msg.data
