    function _estate(uint256[17] memory r, IH.Bundle memory b) private {
        for (uint256 i; i < b.estates.length; ++i) {
            IH.EstateRow memory row = b.estates[i];
            IH.EstateRow memory zero;
            bytes32 key = row.request.recordHash;
            _empty(
