// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;
import { StreamArtistOnboardingTypes as T } from "./StreamArtistOnboardingTypes.sol";

/// @notice Producer-owned complete guard-key inventories. These reads alone install no authority.
interface IStreamArtistAuthorityCheckpoint {
    struct Checkpoint {
        bytes32 schema;
        T.Snapshot ownerState;
        bytes32 replayRoot;
        uint256 replayCount;
        bytes32 nonceRoot;
        uint256 nonceIndexCount;
    }

    struct NonceIndex {
        uint8 kind;
        bytes32 key;
        uint256 prefixCount;
    }
    function authorityCheckpoint() external view returns (Checkpoint memory);
    function authorityReplayAt(uint256 index)
        external
        view
        returns (bytes32 key, T.ReplayCell memory cell);
    function authorityNonceIndexAt(uint256 index) external view returns (NonceIndex memory);
    /// @notice Level zero is the complete leaf word; higher entries are its actual 256-way ancestors.
    /// @dev Index kinds: 1 identity, 2 delegate lane, 3 collaborator account,
    /// 4 rotation acceptance lane, 5 estate acceptance lane. No raw storage pointer is accepted.
    function authorityNonceWordAt(uint8 kind, bytes32 key, uint256 index)
        external
        view
        returns (uint256 prefix, uint256[32] memory words, bool exhausted);
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;
import "./IStreamArtistAuthorityCheckpoint.sol";
import "./StreamArtistOnboardingTypes.sol";
import "./StreamArtistCollaboratorTypes.sol";
import "../../../vendor/openzeppelin/IERC165.sol";

library StreamArtistAuthorityHydrationTypes {
    struct Origin {
        bytes32 surface;
        bytes32 scope;
    }

    struct PolicyKey {
        bytes32 phaseId;
        bytes32 policyHash;
    }

    struct Request {
        uint256 bindingIndex;
        bytes32 artistId;
        uint256 collectionId;
        IStreamArtistAuthorityCheckpoint.Checkpoint[7] expectedSource;
        Origin[][7] replayOrigins;
        PolicyKey[] policies;
    }

    struct Query {
        bytes32 artistId;
        uint256 collectionId;
        bytes32 bindingHash;
        PolicyKey[] policies;
        bytes32[] records;
    }

    struct NonceWord {
        uint256 prefix;
        uint256[32] words;
        bool exhausted;
    }

    struct OwnerData {
        bytes typedState;
        Origin[] origins;
        bytes32[] sourceKeys;
        StreamArtistOnboardingTypes.ReplayCell[] cells;
        NonceWord[] nonces;
    }

    struct Identity {
        StreamArtistOnboardingTypes.Identity item;
        bytes document;
        uint256 nextRegistrationNonce;
        uint256 estateActivity;
        uint256 dormancyActivity;
        uint256 findingActivity;
        bytes[] signatures;
    }

    struct Binding {
        StreamArtistOnboardingTypes.Binding item;
        StreamArtistCollaboratorTypes.BindingTerms terms;
    }

    struct Acceptance {
        bytes32 record;
        uint64 acceptedAt;
    }
}

/// @notice Distinct permissionless operation60. No caller-provided fact is an authorization.
interface IStreamArtistAuthorityHydration is IERC165 {
    function hydrateArtistAuthority(StreamArtistAuthorityHydrationTypes.Request calldata request)
        external
        returns (bytes32);
}

interface IStreamArtistAuthorityHydrationCoordinator {
    function coordinateHydrateArtistAuthority(
        address actor,
        StreamArtistAuthorityHydrationTypes.Request calldata request
    ) external returns (bytes32);
    function authorityHydrationSuite()
        external
        view
        returns (StreamArtistOnboardingTypes.SuiteConfiguration memory);
}

interface IStreamArtistAuthorityHydrationOwner {
    function authorityHydrationState(StreamArtistAuthorityHydrationTypes.Query calldata query)
        external
        view
        returns (bytes memory);
    function authorityHydrationCommitment() external view returns (bytes32);
    function applyArtistAuthorityHydration(
        StreamArtistOnboardingTypes.ActionContext calldata context,
        StreamArtistAuthorityHydrationTypes.Query calldata query,
        StreamArtistAuthorityHydrationTypes.OwnerData calldata data,
        bytes32 commitment
    ) external;
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;
import "../../../vendor/openzeppelin/IERC165.sol";
import "./StreamArtistOnboardingTypes.sol";

library StreamArtistHistoryTypes {
    struct Leaf {
        uint8 laneKind;
        bytes32 laneKey;
        uint64 sequence;
        bytes32 recordHash;
        bytes32 recordChainHash;
    }

    struct Binding {
        address predecessorRegistry;
        uint64 snapshotBlock;
        bytes32 importRoot;
        bytes32 manifestHash;
    }

    struct Receipt {
        uint16 operation;
        bytes32 artistId;
        uint256 collectionId;
        bytes32 recordHash;
    }

    struct Context {
        bytes32 scopeHash;
        bytes32 oldValueHash;
        bytes32 newValueHash;
    }
}

/// @notice Canonical native lanes and the original operation55/56/57 import admission surface.
/// @dev A verified tip or member is history evidence, never an imported authority installation.
interface IStreamArtistHistory is IERC165 {
    event ArtistHistoryImportRootCommitted(
        uint16 schemaVersion,
        address indexed predecessorRegistry,
        bytes32 indexed importRoot,
        uint64 snapshotBlock,
        bytes32 manifestHash,
        bytes32 governanceActionId
    );
    event ArtistHistoryLaneVerified(
        uint16 schemaVersion,
        uint8 indexed laneKind,
        bytes32 indexed laneKey,
        uint256 bindingIndex,
        bytes32 laneTip,
        uint64 recordCount
    );
    event ArtistRegistryCutoverObserved(
        uint16 schemaVersion, address indexed successorTarget, uint64 observedAt
    );

    function artistRecordChainHash(bytes32 artistId) external view returns (bytes32);
    function collectionRecordChainHash(uint256 collectionId) external view returns (bytes32);
    function artistHistoryLane(uint8 kind, bytes32 key)
        external
        view
        returns (bytes32 tip, uint64 count);
    function artistHistoryRecordAt(uint8 kind, bytes32 key, uint64 index)
        external
        view
        returns (bytes32 recordHash, bytes32 chainHash);
    function commitArtistHistoryImportRoot(
        address predecessorRegistry,
        uint64 snapshotBlock,
        bytes32 importRoot,
        bytes32 manifestHash
    ) external;
    function artistHistoryImportContext(
        address predecessorRegistry,
        uint64 snapshotBlock,
