        external
        view
        returns (StreamFinalityRecoveryRecord memory record);

    function activeFinalityRecovery(StreamFinalityScope calldata scope)
        external
        view
        returns (bytes32 recoveryId, bytes32 recoveryRouteHash, uint64 generation);

